// Ventus half of the shared comprehensive TMA matrix.
//
// Use run_ventus_comprehensive_short.py: each case runs in its own bounded GVM
// process.  CUDA and Ventus consume exactly the same CaseSpec manifest, and
// Tensor correctness is generated by the independent TMA C-model.

#include <CL/cl.h>

#include <algorithm>
#include <array>
#include <cstdint>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <limits>
#include <string>
#include <string_view>
#include <vector>

#include "tma_model.h"
#include "ventus_opencl_test.h"
#include "ventus_tma_v2_spec.h"
#include "tma_comprehensive_matrix.h"

namespace {

namespace matrix = tma_comprehensive;
using NeutralCase = matrix::CaseSpec;
using ventus::tma::DecodeAndPlan;
using ventus::tma::Descriptor;
using ventus::tma::Request;
using ventus::tma::Status;

constexpr size_t kWorkgroup = 32;
constexpr uint32_t kSeed = 101u;
constexpr uint8_t kSentinel = 0xa5u;

uint64_t fingerprint64(const void* data, size_t bytes) {
  const auto* input = static_cast<const uint8_t*>(data);
  uint64_t value = 1469598103934665603ull;
  for (size_t index = 0; index < bytes; ++index) {
    value ^= input[index];
    value *= 1099511628211ull;
  }
  return value;
}

struct Options {
  int warmups = 1;
  int repeats = 1;
  std::string shard = "all";
  std::string single_case;
  bool list = false;
  bool validate = false;
};

struct Environment {
  cl_context context = nullptr;
  cl_device_id device = nullptr;
  cl_command_queue queue = nullptr;
  cl_program program = nullptr;
  cl_kernel patch_offset = nullptr;
  cl_kernel tensor_g2s = nullptr;
  cl_kernel tensor_s2g = nullptr;
  cl_kernel tensor_roundtrip = nullptr;
  cl_kernel bulk_g2s = nullptr;
  cl_kernel bulk_s2g = nullptr;
  std::array<cl_kernel, 6> reduce{};

  bool initialize(const std::filesystem::path& source_path) {
    cl_int error = ventus_get_default_device(&context, &device, &queue, nullptr);
    if (error != CL_SUCCESS) return false;
    size_t source_size = 0;
    char* source = ventus_read_text_file(source_path.c_str(), &source_size);
    if (!source) return false;
    const char* sources[] = {source};
    const size_t sizes[] = {source_size};
    program = clCreateProgramWithSource(context, 1, sources, sizes, &error);
    std::free(source);
    if (error != CL_SUCCESS) return false;
    const char* root_environment = std::getenv("VENTUS_ENV_PATH");
    const auto root = root_environment != nullptr
                          ? std::filesystem::path(root_environment)
                          : std::filesystem::current_path();
    const std::string options =
        "-I" + (root / "testcases/_get_case/common").string() + " -I" +
        source_path.parent_path().string();
    error = clBuildProgram(program, 1, &device, options.c_str(), nullptr, nullptr);
    if (error != CL_SUCCESS) {
      ventus_print_build_log(program, device);
      return false;
    }
    const auto make = [&](const char* name) {
      cl_int status = CL_SUCCESS;
      cl_kernel kernel = clCreateKernel(program, name, &status);
      return status == CL_SUCCESS ? kernel : nullptr;
    };
    patch_offset = make("patch_descriptor_base_offset");
    tensor_g2s = make("bench_feature_g2s");
    tensor_s2g = make("bench_feature_s2g");
    tensor_roundtrip = make("bench_feature_roundtrip");
    bulk_g2s = make("bench_comprehensive_bulk_g2s");
    bulk_s2g = make("bench_comprehensive_bulk_s2g");
    const std::array<const char*, 6> names{{
        "bench_comprehensive_reduce_add", "bench_comprehensive_reduce_min",
        "bench_comprehensive_reduce_max", "bench_comprehensive_reduce_and",
        "bench_comprehensive_reduce_or", "bench_comprehensive_reduce_xor"}};
    for (size_t i = 0; i < reduce.size(); ++i) reduce[i] = make(names[i]);
    return patch_offset && tensor_g2s && tensor_s2g && tensor_roundtrip &&
           bulk_g2s && bulk_s2g &&
           std::all_of(reduce.begin(), reduce.end(), [](cl_kernel k) { return k; });
  }

  ~Environment() {
    for (cl_kernel kernel : reduce) if (kernel) clReleaseKernel(kernel);
    if (bulk_s2g) clReleaseKernel(bulk_s2g);
    if (bulk_g2s) clReleaseKernel(bulk_g2s);
    if (tensor_roundtrip) clReleaseKernel(tensor_roundtrip);
    if (tensor_s2g) clReleaseKernel(tensor_s2g);
    if (tensor_g2s) clReleaseKernel(tensor_g2s);
    if (patch_offset) clReleaseKernel(patch_offset);
    if (program) clReleaseProgram(program);
    if (queue) clReleaseCommandQueue(queue);
    if (context) clReleaseContext(context);
  }
};

struct Buffers {
  std::vector<cl_mem> items;
  ~Buffers() {
    for (auto it = items.rbegin(); it != items.rend(); ++it)
      if (*it) clReleaseMemObject(*it);
  }
};

uint8_t pattern_byte(uint32_t seed, uint64_t index) {
  uint32_t value = static_cast<uint32_t>(index) ^ seed ^
                   static_cast<uint32_t>(index >> 32);
  value ^= value >> 16;
  value *= 0x7feb352du;
  value ^= value >> 15;
  value *= 0x846ca68bu;
  value ^= value >> 16;
  return static_cast<uint8_t>((value ^ (value >> 8) ^ (value >> 24)) & 0xffu);
}

std::vector<uint8_t> patterned(size_t bytes, uint32_t seed = kSeed) {
  std::vector<uint8_t> result(bytes);
  for (size_t i = 0; i < bytes; ++i) result[i] = pattern_byte(seed, i);
  return result;
}

uint8_t ventus_dtype(matrix::DType value) {
  switch (value) {
    case matrix::DType::kU8: return VENTUS_TMA_DTYPE_U8;
    case matrix::DType::kU16: return VENTUS_TMA_DTYPE_U16;
    case matrix::DType::kU32: return VENTUS_TMA_DTYPE_U32;
    case matrix::DType::kS32: return VENTUS_TMA_DTYPE_S32;
    case matrix::DType::kU64: return VENTUS_TMA_DTYPE_U64;
    case matrix::DType::kS64: return VENTUS_TMA_DTYPE_S64;
    case matrix::DType::kF16: return VENTUS_TMA_DTYPE_FP16;
    case matrix::DType::kF32: return VENTUS_TMA_DTYPE_FP32;
    case matrix::DType::kF32Ftz: return VENTUS_TMA_DTYPE_FP32_FTZ;
    case matrix::DType::kF64: return VENTUS_TMA_DTYPE_FP64;
    case matrix::DType::kBf16: return VENTUS_TMA_DTYPE_BF16;
    case matrix::DType::kTf32: return VENTUS_TMA_DTYPE_TF32;
    case matrix::DType::kTf32Ftz: return VENTUS_TMA_DTYPE_TF32_FTZ;
    case matrix::DType::kU4Align8: return VENTUS_TMA_DTYPE_B4X16;
    case matrix::DType::kU4Align16: return VENTUS_TMA_DTYPE_B4X16_P64;
    case matrix::DType::kU6Align16: return VENTUS_TMA_DTYPE_B6;
  }
  std::abort();
}

const char* interleave_name(matrix::Interleave value) {
  return value == matrix::Interleave::kNone ? "none"
       : value == matrix::Interleave::k16B ? "16" : "32";
}

const char* swizzle_name(matrix::Swizzle value) {
  switch (value) {
    case matrix::Swizzle::kNone: return "none";
    case matrix::Swizzle::k32B: return "32";
    case matrix::Swizzle::k64B: return "64";
    case matrix::Swizzle::k128B: return "128";
  }
  return "unknown";
}

const char* risk_name(matrix::Risk value) {
  return value == matrix::Risk::kLow ? "low"
       : value == matrix::Risk::kMedium ? "medium" : "high";
}

size_t global_span(const NeutralCase& spec) {
  if (spec.path == matrix::Path::kBulk) return spec.transfer_bytes;
  if (spec.rank == 1)
    return static_cast<size_t>((spec.global_dims[0] * spec.element_bits + 7) / 8);
  return static_cast<size_t>(spec.global_strides_bytes[spec.rank - 2]) *
         static_cast<size_t>(spec.global_dims[spec.rank - 1]);
}

Descriptor descriptor_for(const NeutralCase& spec) {
  Descriptor descriptor{};
  descriptor.words[VENTUS_TMA_V2_WORD_MAGIC] = VENTUS_TMA_V2_MAGIC;
  descriptor.words[VENTUS_TMA_V2_WORD_CONTROL] =
      ventus_dtype(spec.dtype) | (static_cast<uint32_t>(spec.rank) << 5) |
      (static_cast<uint32_t>(spec.interleave) << 8) |
      (static_cast<uint32_t>(spec.swizzle) << 10) |
      (static_cast<uint32_t>(spec.oob_fill) << 18);
  for (int d = 0; d < spec.rank; ++d) {
    descriptor.words[VENTUS_TMA_V2_WORD_GLOBAL_DIMS + d] =
        static_cast<uint32_t>(spec.global_dims[d]);
    descriptor.words[VENTUS_TMA_V2_WORD_BOX_DIMS + d] = spec.box_dims[d];
    descriptor.words[VENTUS_TMA_V2_WORD_ELEMENT_STRIDES + d] =
        spec.element_strides[d];
    if (d + 1 < spec.rank) {
      const uint64_t stride = spec.global_strides_bytes[d];
      const int word = VENTUS_TMA_V2_WORD_GLOBAL_STRIDES + d * 2;
      descriptor.words[word] = static_cast<uint32_t>(stride);
      descriptor.words[word + 1] = static_cast<uint32_t>(stride >> 32);
    }
  }
  return descriptor;
}

ventus::tma::Result plan(const NeutralCase& spec, int direction) {
  Request request{};
  request.direction = direction == 0 ? VENTUS_TMA_G2S : VENTUS_TMA_S2G;
  request.coordinates = spec.coordinates;
  return DecodeAndPlan(descriptor_for(spec), request);
}

std::vector<uint8_t> expected_g2s(const ventus::tma::Result& plan,
                                  const std::vector<uint8_t>& global,
                                  size_t bytes) {
  std::vector<uint8_t> shared(bytes, 0);
  for (const auto& atom : plan.atoms) {
    for (unsigned sl = 0; sl < 16; ++sl) {
      if (((atom.shared_mask >> sl) & 1u) == 0) continue;
      if (atom.fill) {
        shared[atom.shared_atom + sl] = atom.fill_bytes[sl];
      } else {
        for (unsigned gl = 0; gl < 16; ++gl)
          if (((atom.global_mask >> gl) & 1u) && atom.global_to_shared[gl] == sl)
            shared[atom.shared_atom + sl] = global[atom.global_atom + gl];
      }
    }
  }
  return shared;
}

std::vector<uint8_t> expected_s2g(const ventus::tma::Result& plan,
                                  const std::vector<uint8_t>& shared,
                                  size_t bytes) {
  std::vector<uint8_t> global(bytes, kSentinel);
  for (const auto& atom : plan.atoms) {
    if (atom.fill) continue;
    for (unsigned gl = 0; gl < 16; ++gl) {
      if (((atom.global_mask >> gl) & 1u) == 0) continue;
      const unsigned sl = atom.global_to_shared[gl];
      if (sl < 16)
        global[atom.global_atom + gl] = shared[atom.shared_atom + sl];
    }
  }
  return global;
}

uint64_t mismatches(const std::vector<uint8_t>& a,
                    const std::vector<uint8_t>& b) {
  if (a.size() != b.size()) return std::max(a.size(), b.size());
  uint64_t errors = 0;
  for (size_t i = 0; i < a.size(); ++i) errors += a[i] != b[i];
  return errors;
}

cl_mem buffer(Environment& env, Buffers& buffers, cl_mem_flags flags,
              size_t bytes, void* data = nullptr) {
  cl_int error = CL_SUCCESS;
  cl_mem result = clCreateBuffer(env.context, flags, bytes, data, &error);
  if (error != CL_SUCCESS) return nullptr;
  buffers.items.push_back(result);
  return result;
}

bool arg(cl_kernel kernel, cl_uint index, size_t bytes, const void* value) {
  return clSetKernelArg(kernel, index, bytes, value) == CL_SUCCESS;
}

bool launch(Environment& env, cl_kernel kernel) {
  const size_t global = kWorkgroup, local = kWorkgroup;
  return clEnqueueNDRangeKernel(env.queue, kernel, 1, nullptr, &global, &local,
                                0, nullptr, nullptr) == CL_SUCCESS &&
         clFinish(env.queue) == CL_SUCCESS;
}

bool read(Environment& env, cl_mem memory, void* data, size_t bytes) {
  return clEnqueueReadBuffer(env.queue, memory, CL_TRUE, 0, bytes, data, 0,
                             nullptr, nullptr) == CL_SUCCESS;
}

bool write(Environment& env, cl_mem memory, const void* data, size_t bytes) {
  return clEnqueueWriteBuffer(env.queue, memory, CL_TRUE, 0, bytes, data, 0,
                              nullptr, nullptr) == CL_SUCCESS;
}

bool patch(Environment& env, cl_mem descriptor, cl_mem base, uint32_t offset,
           cl_mem identity) {
  if (!arg(env.patch_offset, 0, sizeof(descriptor), &descriptor) ||
      !arg(env.patch_offset, 1, sizeof(base), &base) ||
      !arg(env.patch_offset, 2, sizeof(offset), &offset) ||
      !arg(env.patch_offset, 3, sizeof(identity), &identity)) return false;
  const size_t one = 1;
  return clEnqueueNDRangeKernel(env.queue, env.patch_offset, 1, nullptr, &one,
                                &one, 0, nullptr, nullptr) == CL_SUCCESS &&
         clFinish(env.queue) == CL_SUCCESS;
}

bool configure_tensor(cl_kernel kernel, cl_mem source_desc,
                      cl_mem destination_desc, cl_mem coordinates,
                      cl_mem source, cl_mem destination, cl_mem capture,
                      cl_mem cycles, cl_mem status, uint32_t bytes,
                      uint32_t iterations) {
  const std::array<cl_mem, 8> memories{{source_desc, destination_desc,
      coordinates, source, destination, capture, cycles, status}};
  for (cl_uint i = 0; i < memories.size(); ++i)
    if (!arg(kernel, i, sizeof(cl_mem), &memories[i])) return false;
  return arg(kernel, 8, sizeof(bytes), &bytes) &&
         arg(kernel, 9, sizeof(iterations), &iterations);
}

bool configure_extended(cl_kernel kernel, cl_mem descriptor,
                        cl_mem coordinates, cl_mem source, cl_mem destination,
                        cl_mem capture, cl_mem cycles, cl_mem status,
                        uint32_t bytes, uint32_t iterations, uint32_t offset) {
  const std::array<cl_mem, 7> memories{{descriptor, coordinates, source,
      destination, capture, cycles, status}};
  for (cl_uint i = 0; i < memories.size(); ++i)
    if (!arg(kernel, i, sizeof(cl_mem), &memories[i])) return false;
  return arg(kernel, 7, sizeof(bytes), &bytes) &&
         arg(kernel, 8, sizeof(iterations), &iterations) &&
         arg(kernel, 9, sizeof(offset), &offset);
}

std::string stride_class(const NeutralCase& spec) {
  if (spec.path == matrix::Path::kBulk || spec.rank < 2) return "contiguous";
  uint64_t expected = (spec.global_dims[0] * spec.element_bits + 7) / 8;
  for (int d = 1; d < spec.rank; ++d) {
    if (spec.global_strides_bytes[d - 1] != expected) return "pitched";
    expected *= spec.global_dims[d];
  }
  return "contiguous";
}

void emit_header() {
  std::cout << "gpu,cc,shard,family,case_id,path,direction,dtype,dtype_bits,rank,"
               "logical_bytes,global_span,global_offset,alignment_class,stride_class,"
               "interleave,swizzle,oob_fill,reduce_op,descriptor_mode,risk,repeat,"
               "cycles,event_ns,errors,status,descriptor_state,payload_state,"
               "source_descriptor_va,destination_descriptor_va,"
               "source_descriptor_fingerprint64,destination_descriptor_fingerprint64,"
               "prior_tma_use,descriptor_l2_warm_method,tma_prefetch_before_issue,pair_role\n";
}

void emit(const NeutralCase& spec, int repeat, uint32_t cycles,
          uint64_t errors, uint32_t tma_status, const char* status,
          const char* descriptor_state = "not_applicable",
          uint32_t source_descriptor_va = 0,
          uint32_t destination_descriptor_va = 0,
          uint64_t source_fingerprint = 0,
          uint64_t destination_fingerprint = 0,
          int prior_tma_use = 0,
          const char* pair_role = "not_applicable") {
  const char* backend = std::getenv("VENTUS_BACKEND")
                            ? std::getenv("VENTUS_BACKEND") : "default";
  // The GVM runtime may leave the shared iostream formatting state in hex.
  // Reset it before emitting machine-readable CSV numeric fields.
  std::cout << std::dec << "Ventus," << backend << ',' << spec.shard << ',' << spec.family
            << ',' << spec.id << ',' << matrix::path_name(spec.path) << ','
            << matrix::direction_name(spec.direction) << ','
            << matrix::dtype_name(spec.dtype) << ','
            << static_cast<unsigned>(spec.element_bits) << ',' << spec.rank
            << ',' << spec.transfer_bytes << ',' << global_span(spec) << ','
            << static_cast<unsigned>(spec.global_base_mod128) << ','
            << (spec.global_base_mod128 ? "phase_mod128" : "aligned128") << ','
            << stride_class(spec) << ',' << interleave_name(spec.interleave)
            << ',' << swizzle_name(spec.swizzle) << ','
            << matrix::oob_name(spec.oob_fill) << ','
            << matrix::reduce_name(spec.reduce_op) << ",direct,"
            << risk_name(spec.expected.risk) << ',' << repeat << ',' << cycles
            << ",0," << errors << ',' << status << ',' << descriptor_state
            << ",model_default,0x" << std::hex << source_descriptor_va
            << ",0x" << destination_descriptor_va << ",0x"
            << source_fingerprint << ",0x" << destination_fingerprint
            << std::dec << ',' << prior_tma_use
            << ",patch_descriptor_write,0," << pair_role;
  if (tma_status != VENTUS_TMA_STATUS_OK)
    std::cerr << "TMA_STATUS," << spec.id << ',' << tma_status << '\n';
  std::cout << '\n';
}

cl_kernel tensor_kernel(Environment& env, matrix::Direction direction) {
  return direction == matrix::Direction::kG2s ? env.tensor_g2s
       : direction == matrix::Direction::kS2g ? env.tensor_s2g
                                               : env.tensor_roundtrip;
}

bool run_tensor(Environment& env, const NeutralCase& spec,
                const Options& options) {
  const int direction = spec.direction == matrix::Direction::kG2s ? 0
                      : spec.direction == matrix::Direction::kS2g ? 1 : 2;
  const auto gp = plan(spec, 0), sp = plan(spec, 1);
  if ((direction != 1 && gp.status != Status::kOk) ||
      (direction != 0 && sp.status != Status::kOk)) {
    std::cerr << "MODEL_ERROR," << spec.id << ',' << gp.detail << ',' << sp.detail << '\n';
    emit(spec, -1, 0, 1, 0xffffffffu, "model_rejected");
    return false;
  }
  const size_t allocation = global_span(spec), phase = spec.global_base_mod128;
  const auto source = patterned(allocation);
  auto shared_seed = patterned(spec.transfer_bytes);
  Descriptor source_desc = descriptor_for(spec), destination_desc = source_desc;
  std::array<int32_t, 32> coordinates{};
  std::copy(spec.coordinates.begin(), spec.coordinates.end(), coordinates.begin());
  Buffers buffers;
  cl_mem coordinates_buffer = buffer(env, buffers, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                                     sizeof(coordinates), coordinates.data());
  cl_mem seed_buffer = buffer(env, buffers, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                              shared_seed.size(), shared_seed.data());
  if (!coordinates_buffer || !seed_buffer) return false;
  cl_kernel kernel = tensor_kernel(env, spec.direction);
  bool all_ok = true;
  if (options.warmups != 0 || options.repeats != 2) return false;
  std::vector<uint8_t> source_storage(allocation + 128, kSentinel);
  std::copy(source.begin(), source.end(), source_storage.begin() + phase);
  std::vector<uint8_t> destination_storage(allocation + 128, kSentinel);
  std::vector<uint8_t> capture(spec.transfer_bytes, 0);
  std::array<uint32_t, 2> cycles{};
  uint32_t status = 0xffffffffu;
  std::array<uint32_t, 2> source_identity{}, destination_identity{};
  cl_mem source_desc_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(source_desc.words), source_desc.words.data());
  cl_mem destination_desc_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(destination_desc.words), destination_desc.words.data());
  cl_mem source_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      source_storage.size(), source_storage.data());
  cl_mem destination_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      destination_storage.size(), destination_storage.data());
  cl_mem capture_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      capture.size(), capture.data());
  cl_mem cycles_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(cycles), cycles.data());
  cl_mem status_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(status), &status);
  cl_mem source_identity_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(source_identity), source_identity.data());
  cl_mem destination_identity_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(destination_identity), destination_identity.data());
  if (!source_desc_buffer || !destination_desc_buffer || !source_buffer ||
      !destination_buffer || !capture_buffer || !cycles_buffer ||
      !status_buffer || !source_identity_buffer ||
      !destination_identity_buffer ||
      !patch(env, source_desc_buffer, source_buffer, phase,
             source_identity_buffer) ||
      !patch(env, destination_desc_buffer, destination_buffer, phase,
             destination_identity_buffer))
    return false;
  Descriptor patched_source{}, patched_destination{};
  if (!read(env, source_desc_buffer, patched_source.words.data(),
            sizeof(patched_source.words)) ||
      !read(env, destination_desc_buffer, patched_destination.words.data(),
            sizeof(patched_destination.words)) ||
      !read(env, source_identity_buffer, source_identity.data(),
            sizeof(source_identity)) ||
      !read(env, destination_identity_buffer, destination_identity.data(),
            sizeof(destination_identity)))
    return false;

  cl_mem kernel_source = direction == 1 ? seed_buffer : source_buffer;
  const uint32_t iterations = options.repeats;
  if (!configure_tensor(kernel, source_desc_buffer, destination_desc_buffer,
                        coordinates_buffer, kernel_source,
                        destination_buffer, capture_buffer, cycles_buffer,
                        status_buffer, spec.transfer_bytes, iterations) ||
      !launch(env, kernel) ||
      !read(env, cycles_buffer, cycles.data(), sizeof(cycles)) ||
      !read(env, status_buffer, &status, sizeof(status)))
    return false;

  for (int repeat = 0; repeat < options.repeats; ++repeat) {
    uint64_t errors = 0;
    if (direction == 0) {
      if (!read(env, capture_buffer, capture.data(), capture.size())) return false;
      errors = mismatches(
          capture, expected_g2s(gp, source, spec.transfer_bytes));
    } else {
      if (!read(env, destination_buffer, destination_storage.data(),
                destination_storage.size())) return false;
      std::vector<uint8_t> actual(destination_storage.begin() + phase,
                                  destination_storage.begin() + phase + allocation);
      std::vector<uint8_t> expected;
      if (direction == 1) {
        expected = expected_s2g(sp, shared_seed, allocation);
      } else if (spec.dtype == matrix::DType::kU6Align16) {
        expected.assign(allocation, kSentinel);
        for (size_t offset = 0; offset < allocation; ++offset)
          if ((offset & 15u) < 12u) expected[offset] = source[offset];
      } else {
        expected = expected_s2g(
            sp, expected_g2s(gp, source, spec.transfer_bytes), allocation);
      }
      errors = mismatches(actual, expected);
    }
    const bool ok = errors == 0 && status == VENTUS_TMA_STATUS_OK;
    all_ok &= ok;
    emit(spec, repeat, cycles[repeat], errors, status,
         ok ? "ok" : "validation_error",
         repeat == 0 ? "tmau_cold_first_use_fresh_allocation"
                     : "tmau_hot_reuse",
         direction == 1 ? 0 : source_identity[0],
         direction == 0 ? 0 : destination_identity[0],
         direction == 1 ? 0 : fingerprint64(
             patched_source.words.data(), sizeof(patched_source.words)),
         direction == 0 ? 0 : fingerprint64(
             patched_destination.words.data(), sizeof(patched_destination.words)),
         repeat, repeat == 0 ? "cold" : "hot");
  }
  return all_ok;
}

bool run_bulk(Environment& env, const NeutralCase& spec,
              const Options& options) {
  const size_t phase = spec.global_base_mod128;
  std::vector<uint8_t> source_storage(spec.transfer_bytes + 128, kSentinel);
  const auto seed = patterned(spec.transfer_bytes);
  std::copy(seed.begin(), seed.end(), source_storage.begin() + phase);
  std::vector<uint8_t> destination(spec.transfer_bytes + 128, kSentinel);
  std::vector<uint8_t> capture(spec.transfer_bytes, 0);
  std::vector<uint32_t> cycles(std::max(options.warmups, options.repeats), 0);
  uint32_t status = 0xffffffffu;
  Descriptor dummy{};
  std::array<int32_t, 32> coordinates{};
  Buffers buffers;
  cl_mem dummy_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                               sizeof(dummy.words), dummy.words.data());
  cl_mem coordinates_buffer = buffer(env, buffers, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                                     sizeof(coordinates), coordinates.data());
  cl_mem source_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                source_storage.size(), source_storage.data());
  cl_mem seed_buffer = buffer(env, buffers, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                              seed.size(), const_cast<uint8_t*>(seed.data()));
  cl_mem destination_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                     destination.size(), destination.data());
  cl_mem capture_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                 capture.size(), capture.data());
  cl_mem cycles_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                cycles.size() * sizeof(uint32_t), cycles.data());
  cl_mem status_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                sizeof(status), &status);
  cl_kernel kernel = spec.direction == matrix::Direction::kG2s
                         ? env.bulk_g2s : env.bulk_s2g;
  const auto execute = [&](int iterations) {
    cl_mem input = spec.direction == matrix::Direction::kG2s
                       ? source_buffer : seed_buffer;
    return configure_extended(kernel, dummy_buffer, coordinates_buffer, input,
                              destination_buffer, capture_buffer, cycles_buffer,
                              status_buffer, spec.transfer_bytes, iterations,
                              phase) && launch(env, kernel);
  };
  if (options.warmups && !execute(options.warmups)) return false;
  if (options.warmups &&
      !write(env, destination_buffer, destination.data(), destination.size())) return false;
  if (!execute(options.repeats) ||
      !read(env, cycles_buffer, cycles.data(), options.repeats * sizeof(uint32_t)) ||
      !read(env, status_buffer, &status, sizeof(status))) return false;
  uint64_t errors = 0;
  if (spec.direction == matrix::Direction::kG2s) {
    if (!read(env, capture_buffer, capture.data(), capture.size())) return false;
    errors = mismatches(capture, seed);
  } else {
    if (!read(env, destination_buffer, destination.data(), destination.size())) return false;
    std::vector<uint8_t> actual(destination.begin() + phase,
                                destination.begin() + phase + spec.transfer_bytes);
    errors = mismatches(actual, seed);
  }
  const bool ok = errors == 0 && status == VENTUS_TMA_STATUS_OK;
  for (int i = 0; i < options.repeats; ++i)
    emit(spec, i, cycles[i], errors, status, ok ? "ok" : "validation_error");
  return ok;
}

uint32_t apply_reduce(matrix::ReduceOp op, bool signed_dtype, uint32_t old,
                      uint32_t operand) {
  switch (op) {
    case matrix::ReduceOp::kAdd: return old + operand;
    case matrix::ReduceOp::kMin:
      return signed_dtype ? (static_cast<int32_t>(old) < static_cast<int32_t>(operand) ? old : operand)
                          : std::min(old, operand);
    case matrix::ReduceOp::kMax:
      return signed_dtype ? (static_cast<int32_t>(old) > static_cast<int32_t>(operand) ? old : operand)
                          : std::max(old, operand);
    case matrix::ReduceOp::kAnd: return old & operand;
    case matrix::ReduceOp::kOr: return old | operand;
    case matrix::ReduceOp::kXor: return old ^ operand;
    case matrix::ReduceOp::kNone: return old;
  }
  return old;
}

bool run_reduce(Environment& env, const NeutralCase& spec,
                const Options& options) {
  const size_t allocation = global_span(spec), phase = spec.global_base_mod128;
  std::vector<uint32_t> storage((allocation + 128) / 4, kSentinel * 0x01010101u);
  const size_t word_phase = phase / 4;
  for (size_t i = 0; i < allocation / 4; ++i)
    storage[word_phase + i] = 0x91e10da5u ^ static_cast<uint32_t>(i * 0x9e37u);
  const auto initial = storage;
  std::vector<uint32_t> cycles(std::max(options.warmups, options.repeats), 0);
  uint32_t status = 0xffffffffu;
  Descriptor descriptor = descriptor_for(spec);
  std::array<int32_t, 32> coordinates{};
  Buffers buffers;
  cl_mem descriptor_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                     sizeof(descriptor.words), descriptor.words.data());
  cl_mem coordinates_buffer = buffer(env, buffers, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                                     sizeof(coordinates), coordinates.data());
  cl_mem storage_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                 storage.size() * sizeof(uint32_t), storage.data());
  cl_mem dummy_buffer = buffer(env, buffers, CL_MEM_READ_WRITE, 4);
  cl_mem cycles_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                cycles.size() * sizeof(uint32_t), cycles.data());
  cl_mem status_buffer = buffer(env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
                                sizeof(status), &status);
  std::array<uint32_t, 2> identity{};
  cl_mem identity_buffer = buffer(
      env, buffers, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR,
      sizeof(identity), identity.data());
  if (!identity_buffer ||
      !patch(env, descriptor_buffer, storage_buffer, phase, identity_buffer))
    return false;
  const size_t kernel_index = static_cast<size_t>(spec.reduce_op) - 1;
  cl_kernel kernel = env.reduce[kernel_index];
  const auto execute = [&](int iterations) {
    return configure_extended(kernel, descriptor_buffer, coordinates_buffer,
                              dummy_buffer, dummy_buffer, dummy_buffer,
                              cycles_buffer, status_buffer, spec.transfer_bytes,
                              iterations, 0) && launch(env, kernel);
  };
  if (options.warmups && !execute(options.warmups)) return false;
  if (options.warmups &&
      !write(env, storage_buffer, initial.data(), initial.size() * sizeof(uint32_t))) return false;
  if (!execute(options.repeats) ||
      !read(env, cycles_buffer, cycles.data(), options.repeats * sizeof(uint32_t)) ||
      !read(env, status_buffer, &status, sizeof(status)) ||
      !read(env, storage_buffer, storage.data(), storage.size() * sizeof(uint32_t))) return false;
  std::vector<uint32_t> expected = initial;
  const auto reduce_plan = plan(spec, 1);
  if (reduce_plan.status != Status::kOk) return false;
  std::vector<uint8_t> shared_bytes(spec.transfer_bytes);
  for (size_t i = 0; i < shared_bytes.size() / 4; ++i) {
    const uint32_t operand =
        0x01020304u ^ static_cast<uint32_t>(i * 0x1021u);
    std::memcpy(shared_bytes.data() + i * 4, &operand, sizeof(operand));
  }
  const auto mapped_bytes = expected_s2g(reduce_plan, shared_bytes, allocation);
  std::vector<uint8_t> mapped_words(allocation / 4, 0);
  for (const auto& atom : reduce_plan.atoms)
    for (unsigned lane = 0; lane < 16; ++lane)
      if ((atom.global_mask >> lane) & 1u)
        mapped_words[(atom.global_atom + lane) / 4] = 1;
  for (int r = 0; r < options.repeats; ++r)
    for (size_t i = 0; i < allocation / 4; ++i) {
      if (!mapped_words[i]) continue;
      uint32_t operand = 0;
      std::memcpy(&operand, mapped_bytes.data() + i * 4, sizeof(operand));
      expected[word_phase + i] = apply_reduce(
          spec.reduce_op, spec.dtype == matrix::DType::kS32,
          expected[word_phase + i], operand);
    }
  uint64_t errors = 0;
  for (size_t i = 0; i < storage.size(); ++i) errors += storage[i] != expected[i];
  const bool ok = errors == 0 && status == VENTUS_TMA_STATUS_OK;
  for (int i = 0; i < options.repeats; ++i)
    emit(spec, i, cycles[i], errors, status, ok ? "ok" : "validation_error");
  return ok;
}

Options parse_options(int argc, char** argv) {
  Options options;
  for (int i = 1; i < argc; ++i) {
    const std::string_view value(argv[i]);
    const auto next = [&](const char* name) {
      if (++i >= argc) { std::cerr << "missing " << name << '\n'; std::exit(2); }
      return argv[i];
    };
    if (value == "--shard") options.shard = next("--shard");
    else if (value == "--case") options.single_case = next("--case");
    else if (value == "--warmups") options.warmups = std::atoi(next("--warmups"));
    else if (value == "--repeats") options.repeats = std::atoi(next("--repeats"));
    else if (value == "--list") options.list = true;
    else if (value == "--validate") options.validate = true;
    else if (value == "--csv") {}
    else { std::cerr << "unknown option " << value << '\n'; std::exit(2); }
  }
  if (!matrix::valid_shard(options.shard) || options.warmups < 0 ||
      options.warmups > 1 || options.repeats < 1 || options.repeats > 3) {
    std::cerr << "invalid shard/warmups/repeats\n";
    std::exit(2);
  }
  return options;
}

}  // namespace

int main(int argc, char** argv) {
  const Options options = parse_options(argc, argv);
  std::vector<NeutralCase> cases = matrix::cases_for_shard(options.shard);
  if (!options.single_case.empty()) {
    const NeutralCase* selected = matrix::find_case(cases, options.single_case);
    if (!selected) { std::cerr << "case not found\n"; return 2; }
    cases = {*selected};
  }
  if (options.list) {
    for (const auto& spec : cases) std::cout << spec.id << '\n';
    return 0;
  }
  if (options.validate) {
    int failures = 0;
    for (const auto& spec : cases) {
      if (spec.path == matrix::Path::kBulk) continue;
      const bool needs_g2s = spec.direction != matrix::Direction::kS2g;
      const bool needs_s2g = spec.direction != matrix::Direction::kG2s;
      const auto gp = plan(spec, 0);
      const auto sp = plan(spec, 1);
      if ((needs_g2s && gp.status != Status::kOk) ||
          (needs_s2g && sp.status != Status::kOk)) {
        std::cerr << "MODEL_REJECT," << spec.id << ",g2s="
                  << ventus::tma::StatusName(gp.status) << ':' << gp.detail
                  << ",s2g=" << ventus::tma::StatusName(sp.status) << ':'
                  << sp.detail << '\n';
        ++failures;
      }
    }
    if (!failures)
      std::cout << "validated " << cases.size() << " matrix cases\n";
    return failures ? 1 : 0;
  }
  const auto executable = std::filesystem::weakly_canonical(
      std::filesystem::absolute(argv[0]));
  const auto source = executable.parent_path() / "ventus_tma_comprehensive.cl";
  Environment environment;
  if (!environment.initialize(source)) return 1;
  emit_header();
  int failures = 0;
  for (const auto& spec : cases) {
    std::cerr << "CASE_START," << spec.shard << ',' << spec.id << '\n';
    bool ok = spec.path == matrix::Path::kBulk
                  ? run_bulk(environment, spec, options)
              : spec.path == matrix::Path::kReduce
                  ? run_reduce(environment, spec, options)
                  : run_tensor(environment, spec, options);
    failures += !ok;
  }
  return failures ? 1 : 0;
}
